<button class="w-full py-3 px-4 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface font-label-md text-label-md flex items-center justify-center gap-3 transition-colors shadow-sm" onclick="handleGoogleLogin()" type="button">
<svg class="w-5 h-5" viewBox="0 0 24 24">
<path d="M12 5c1.6 0 3 .6 4.1 1.7l3.1-3.1C17.3 1.8 14.8 1 12 1 7.4 1 3.5 3.6 1.6 7.4l3.7 2.9C6.2 7.3 8.9 5 12 5z" fill="#EA4335"></path>
<path d="M23.5 12.3c0-.8-.1-1.6-.2-2.3H12v4.5h6.5c-.3 1.5-1.1 2.8-2.4 3.7l3.7 2.9c2.2-2 3.7-5.1 3.7-8.8z" fill="#4285F4"></path>
<path d="M5.3 14.7c-.2-.7-.4-1.5-.4-2.4s.2-1.7.4-2.4L1.6 7.4C.6 9.3 0 11.5 0 14s.6 4.7 1.6 6.6l3.7-2.9z" fill="#FBBC05"></path>
<path d="M12 23c3.2 0 6-1.1 8-3l-3.7-2.9c-1.1.7-2.5 1.2-4.3 1.2-3.1 0-5.8-2.3-6.7-5.3L1.6 16c1.9 3.8 5.8 7 10.4 7z" fill="#34A853"></path>
</svg>
<span class="">Masuk dengan Google</span>
</button>
<!-- Register Link Footer -->
<div class="mt-6 pt-5 text-center">
<p class="font-body-md text-body-md text-on-surface-variant">
              Belum punya akun?
              <a class="font-label-md text-label-md text-primary font-semibold hover:underline ml-1" data-path="daftar-akun" href="#">
                Daftar Akun Baru
              </a>
</p>
</div>
<!-- Partner Onboarding Promo Micro-banner -->
<div class="mt-4 p-3.5 rounded-lg bg-surface-container flex items-center justify-between gap-3">
<div class="flex items-center gap-2.5">
<div class="w-8 h-8 rounded-md bg-secondary-container text-on-surface flex items-center justify-center flex-shrink-0">
<span class="material-symbols-outlined text-[18px]">domain_add</span>
</div>
<div class="text-left">
<p class="font-label-md text-label-md text-on-surface leading-snug">Punya lapangan olahraga?</p>
<p class="font-body-sm text-body-sm text-on-surface-variant">Daftarkan arena Anda &amp; jangkau ribuan atlet.</p>
</div>
</div>
<a class="flex-shrink-0 px-3 py-1.5 rounded-md bg-surface-container-high hover:bg-surface-bright text-primary font-label-sm text-label-sm transition-colors flex items-center gap-1" data-path="partner-onboarding" href="#">
<span class="">Daftar Mitra</span>
<span class="material-symbols-outlined text-[14px]">chevron_right</span>
</a>
</div>
</div>
</div>
</div>
<!-- Quick Support Assistance Bottom Ribbon -->

</div>
</div>
<script>
  let currentRole = 'player';

  function selectRole(role) {
    currentRole = role;
    const playerBtn = document.getElementById('role-player-btn');
    const partnerBtn = document.getElementById('role-partner-btn');
    const roleSubtitle = document.getElementById('role-subtitle');
    const btnText = document.getElementById('btnText');

    if (role === 'player') {
      playerBtn.className = 'flex-1 py-2 px-3 rounded-md font-label-md text-label-md flex items-center justify-center gap-2 transition-all duration-200 bg-primary-container text-on-primary-container shadow-md';
      partnerBtn.className = 'flex-1 py-2 px-3 rounded-md font-label-md text-label-md flex items-center justify-center gap-2 transition-all duration-200 text-on-surface-variant hover:text-on-surface';
      roleSubtitle.textContent = 'Masuk ke akun Anda untuk booking lapangan dan kelola pesanan olahraga dengan mudah.';
      btnText.textContent = 'Masuk Sekarang';
    } else {
      partnerBtn.className = 'flex-1 py-2 px-3 rounded-md font-label-md text-label-md flex items-center justify-center gap-2 transition-all duration-200 bg-primary-container text-on-primary-container shadow-md';
      playerBtn.className = 'flex-1 py-2 px-3 rounded-md font-label-md text-label-md flex items-center justify-center gap-2 transition-all duration-200 text-on-surface-variant hover:text-on-surface';
      roleSubtitle.textContent = 'Masuk ke dashboard mitra untuk memantau jadwal sewa, pendapatan, dan slot lapangan Anda.';
      btnText.textContent = 'Masuk ke Dashboard Mitra';
    }
  }

  function togglePasswordVisibility() {
    const passwordInput = document.getElementById('password');
    const eyeIcon = document.getElementById('passwordEyeIcon');
    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      eyeIcon.textContent = 'visibility_off';
    } else {
      passwordInput.type = 'password';
      eyeIcon.textContent = 'visibility';
    }
  }

  function handleLogin(event) {
    event.preventDefault();
    const btn = document.getElementById('submitButton');
    const btnText = document.getElementById('btnText');
    const originalText = btnText.textContent;

    btnText.textContent = 'Memverifikasi...';
    btn.classList.add('opacity-75', 'cursor-wait');

    setTimeout(() => {
      btnText.textContent = 'Berhasil Masuk';
      btn.classList.remove('opacity-75', 'cursor-wait');
      btn.classList.add('bg-primary-container');
    }, 1000);
  }

  function handleGoogleLogin() {
    alert('Menghubungkan ke layanan Google Autentikasi...');
  }
</script></main><footer class="w-full bg-surface-container-lowest py-space-2xl"><div class="w-full px-margin flex flex-col md:flex-row items-center justify-between gap-space-lg"><div class="flex items-center gap-space-md"><img alt="locArena full brand logo with green icon and clean white/green locArena typography" class="h-6 w-auto object-contain opacity-80" src="https://lh3.googleusercontent.com/aida/AEtjO1VmNjDPW_ohdH-PwcGactRo2AyM8HMhNfI7LuB3-xiXNYPPG0dtvIPfYKZ9UzawgjSS5PkIyKAb4kj6W0RtW8DjJOIiPW9oVFiUv-ZGvlgL9AclNS02TW4pbi7miYyY6yUtWNqGQl8Uozcz03Ed9wvkWxeu2wx34HE4RSgtNCAGSsMPrMMFn_6o3osWeRMA0kiBNmC7fcaNdvBsw07w_pO6GmFUptatqWazVNrse46LhcLBeEW1b-OJPvQ"><p class="font-body-sm text-body-sm text-on-surface-variant">© 2024 locArena Inc. Hak Cipta Dilindungi Undang-Undang.</p></div><div class="flex items-center gap-space-xl"><a class="font-label-sm text-label-sm text-on-surface-variant hover:text-primary uppercase transition-colors" data-path="pusat-bantuan" href="#">Pusat Bantuan</a><a class="font-label-sm text-label-sm text-on-surface-variant hover:text-primary uppercase transition-colors" data-path="syarat-ketentuan" href="#">Syarat &amp; Ketentuan</a><a class="font-label-sm text-label-sm text-on-surface-variant hover:text-primary uppercase transition-colors" data-path="kebijakan-privasi" href="#">Kebijakan Privasi</a></div></div></footer>

